class Solution {
    public int subarraysWithMoreOnesThanZeroes(int[] nums) {
        int n = nums.length, off = n + 1;
        int[] bit = new int[2 * n + 3];
        long ans = 0;
        int pre = 0;
        add(bit, pre + off);
        for (int x : nums) {
            pre += x == 1 ? 1 : -1;
            ans += query(bit, pre + off - 1);
            add(bit, pre + off);
        }
        return (int) (ans % 1_000_000_007);
    }

    private void add(int[] bit, int i) {
        for (; i < bit.length; i += i & -i) bit[i]++;
    }

    private long query(int[] bit, int i) {
        long s = 0;
        for (; i > 0; i -= i & -i) s += bit[i];
        return s;
    }
}
